import{_ as o,o as e,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"アクセス制御","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/access.md","filePath":"ja/guides/access.md","lastUpdated":1792323081000}'),l={name:"ja/guides/access.md"};function d(n,t,i,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="アクセス制御" tabindex="-1">アクセス制御 <a class="header-anchor" href="#アクセス制御" aria-label="Permalink to &quot;アクセス制御&quot;">​</a></h1><p>Memoh のアクセス制御は 2 つの層に分かれています:</p><ul><li><strong>チャネルメンバー</strong>: Telegram、Discord、Feishu、QQ などの IM チャネルから来るアイデンティティを制御します。</li><li><strong>ワークスペースメンバー</strong>: クライアントとワークスペースにおける Memoh の登録ユーザーを制御します。</li></ul><p>従来の ACL ルールモデルも引き続き存在しますが、現在は主にチャネルのチャット権限の裏側で動く高度なエンジンという位置付けです。日常的な設定は、Bot の <strong>アクセス</strong> タブから、<strong>チャネルメンバー</strong> と <strong>ワークスペースメンバー</strong> の 2 つの入口を使って始めるのがよいでしょう。</p><hr><h2 id="基本モデル" tabindex="-1">基本モデル <a class="header-anchor" href="#基本モデル" aria-label="Permalink to &quot;基本モデル&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>アイデンティティ</th><th>制御する内容</th></tr></thead><tbody><tr><td><strong>チャネルメンバー</strong></td><td>IM プラットフォーム上で観測されたチャネルアイデンティティ</td><td>そのプラットフォーム上のアイデンティティが Bot とチャットできるか、そして IM コマンドで Bot を管理できるか</td></tr><tr><td><strong>ワークスペースメンバー</strong></td><td>Memoh の登録ユーザーアカウント</td><td>そのユーザーがクライアントで Bot を使えるか、ファイルを読み書きできるか、ワークスペースコマンドを実行できるか、Bot の設定を管理できるか</td></tr></tbody></table><p>この 2 つの層は、アカウント連携でつなげられます。ワークスペースのユーザーは <strong>Profile -&gt; Connected Accounts</strong> でワンタイムコードを生成し、IM でいずれかの Memoh Bot に <code>/link &lt;code&gt;</code> を送ることで、そのメッセージを送ったチャネルアイデンティティを自分の Memoh アカウントに連携できます。</p><p>連携そのものはアクセス権限を付与しません。アイデンティティをつなぐ役割だけを担います。実際の権限は、あくまでチャネルメンバー、ワークスペースメンバー、Bot のオーナー、またはシステム管理者という立場から来ます。</p><hr><h2 id="クイックスタート" tabindex="-1">クイックスタート <a class="header-anchor" href="#クイックスタート" aria-label="Permalink to &quot;クイックスタート&quot;">​</a></h2><h3 id="任意の-im-ユーザーにチャットを許可する" tabindex="-1">任意の IM ユーザーにチャットを許可する <a class="header-anchor" href="#任意の-im-ユーザーにチャットを許可する" aria-label="Permalink to &quot;任意の IM ユーザーにチャットを許可する&quot;">​</a></h3><ol><li>Bot の <strong>アクセス</strong> タブを開きます。</li><li><strong>チャネルメンバー</strong> に進みます。</li><li><strong>アクセスモード</strong> を <strong>ブラックリストモード</strong> に設定します。</li><li>メンバーリストは空のままにするか、ブロックしたいアイデンティティだけを追加します。</li></ol><p>ブラックリストモードは、ACL のデフォルト効果が <code>allow</code> であることを意味します。拒否ルールにマッチしない限り、誰でもチャットできます。</p><h3 id="指定した-im-アイデンティティだけを許可する" tabindex="-1">指定した IM アイデンティティだけを許可する <a class="header-anchor" href="#指定した-im-アイデンティティだけを許可する" aria-label="Permalink to &quot;指定した IM アイデンティティだけを許可する&quot;">​</a></h3><ol><li><strong>チャネルメンバー</strong> を開きます。</li><li><strong>アクセスモード</strong> を <strong>ホワイトリストモード</strong> に設定します。</li><li>アクセスを許可するチャネルアイデンティティを追加します。</li><li>許可する各アイデンティティで <strong>チャット</strong> のチェックを維持します。</li></ol><p>ホワイトリストモードは、ACL のデフォルト効果が <code>deny</code> であることを意味します。許可ルールにマッチしたアイデンティティだけがチャットできます。</p><h3 id="web-ユーザーに権限を与える" tabindex="-1">Web ユーザーに権限を与える <a class="header-anchor" href="#web-ユーザーに権限を与える" aria-label="Permalink to &quot;Web ユーザーに権限を与える&quot;">​</a></h3><ol><li><strong>ワークスペースメンバー</strong> を開きます。</li><li>特定のメンバーを追加するか、<strong>すべてのメンバー</strong> を追加します。</li><li>そのメンバーに持たせたい権限を選びます。</li></ol><p>ワークスペースアクセスは Memoh の登録ユーザー向けです。ユーザーが自分の IM アイデンティティを連携しない限り、IM のチャット権限とは別物です。</p><hr><h2 id="チャネルメンバー" tabindex="-1">チャネルメンバー <a class="header-anchor" href="#チャネルメンバー" aria-label="Permalink to &quot;チャネルメンバー&quot;">​</a></h2><p>チャネルメンバーは、IM 側のアクセス制御の入口です。</p><p>1 行が 1 つの<strong>チャネルアイデンティティ</strong>（1 人の Telegram ユーザーや Discord メンバー）、または 1 つの<strong>グループチャット</strong>（後述）を表します。メンバーはカードヘッダーのインライン選択から追加でき、個人のアイデンティティとグループチャットの候補は同じドロップダウン内にセクション分けで表示されます。各行には互いに独立した 2 つの権限があります:</p><table tabindex="0"><thead><tr><th>権限</th><th>意味</th></tr></thead><tbody><tr><td><strong>チャット</strong></td><td>その IM アイデンティティから届く受信メッセージが Bot をトリガーできるかを制御します。</td></tr><tr><td><strong>管理</strong></td><td>そのアイデンティティが IM のスラッシュコマンドで Bot を管理できるかを制御します。管理権限が自動的にチャット権限を与えることはありません。</td></tr></tbody></table><h3 id="チャット" tabindex="-1">チャット <a class="header-anchor" href="#チャット" aria-label="Permalink to &quot;チャット&quot;">​</a></h3><p>チャットのチェックボックスの裏側にあるのは、<code>chat.trigger</code> の ACL ルールです。</p><p><strong>ブラックリストモード</strong>では:</p><ul><li>デフォルトは <code>allow</code> です</li><li>アイデンティティを追加する、またはチャットのチェックを外すと、拒否ルールが作成されます</li><li>チャットにチェックを入れると、そのアイデンティティの拒否ルールが削除されます</li></ul><p><strong>ホワイトリストモード</strong>では:</p><ul><li>デフォルトは <code>deny</code> です</li><li>アイデンティティを追加する、またはチャットにチェックを入れると、許可ルールが作成されます</li><li>チャットのチェックを外すと、そのアイデンティティの許可ルールが削除されます</li></ul><h3 id="管理" tabindex="-1">管理 <a class="header-anchor" href="#管理" aria-label="Permalink to &quot;管理&quot;">​</a></h3><p>管理のチェックボックスは、そのチャネルアイデンティティに対するローカルの Channel Access オーバーライドを書き込みます。</p><p>管理権限は IM コマンドで使われます。これにより、あるチャネルアイデンティティが owner レベルのスラッシュコマンドフローで Bot の管理者として振る舞えるようになります。チャット権限とは意図的に切り離されています: あるアイデンティティが管理権限を持っていても、チャットがオフだったり ACL が拒否していたりすれば、その通常のチャットメッセージは引き続きブロックされます。</p><h3 id="グループチャットをメンバーにする" tabindex="-1">グループチャットをメンバーにする <a class="header-anchor" href="#グループチャットをメンバーにする" aria-label="Permalink to &quot;グループチャットをメンバーにする&quot;">​</a></h3><p>個別のアイデンティティのほかに、<strong>グループチャット</strong>全体を 1 行のメンバーとして追加することもできます。グループチャットの候補は Bot が各チャネルで観測した会話から来ており、行には「グループ」バッジが付きます。</p><ul><li>グループ行の<strong>チャット</strong>チェックボックスは「このグループにいる全員」を意味します——ホワイトリストモードではグループ全体を許可し、ブラックリストモードではグループ全体をブロックします。</li><li><strong>グループに管理権限はありません。</strong> 管理者は常に個別のチャネルアイデンティティです。</li><li>「この人が、このグループの中で」のような組み合わせを表現したい場合は、引き続き高度な ACL ルールを使います。</li></ul><h3 id="プラットフォームメンバー" tabindex="-1">プラットフォームメンバー <a class="header-anchor" href="#プラットフォームメンバー" aria-label="Permalink to &quot;プラットフォームメンバー&quot;">​</a></h3><p>あるチャネルアイデンティティがこの Bot のワークスペースメンバーに連携済みの場合、その行はプラットフォームメンバーとしてマークされます。</p><p>対応するワークスペースメンバーが <strong>ワークスペースメンバー</strong> で <strong>管理</strong> 権限を持っているとき、そのチャネルアイデンティティは自動的に管理権限を継承します。チャネルメンバーの行には、この管理権限が継承によるものだと表示されます。チャネルメンバー側で管理権限を切り替えると、Memoh はローカルオーバーライドを書き込みます:</p><ul><li>ローカルで<strong>オン</strong>にすると、そのチャネルアイデンティティに管理権限を強制的に与えます</li><li>ローカルで<strong>オフ</strong>にすると、そのチャネルアイデンティティが継承した管理権限を抑制します</li><li><strong>継承に戻す</strong>と、ローカルオーバーライドが削除され、再びワークスペースメンバーの権限に従います</li></ul><p>チャネルメンバーから削除できるのは、純粋にローカルなチャネル行だけです。プラットフォームメンバーの行はアカウント連携から来るものなので、権限設定か連携の解除によって管理してください。</p><hr><h2 id="ワークスペースメンバー" tabindex="-1">ワークスペースメンバー <a class="header-anchor" href="#ワークスペースメンバー" aria-label="Permalink to &quot;ワークスペースメンバー&quot;">​</a></h2><p>ワークスペースメンバーは、Web／ワークスペース側のアクセス制御の入口です。</p><p>権限を与えられる対象は次のとおりです:</p><ul><li><strong>特定のメンバー</strong></li><li><strong>すべてのメンバー</strong></li></ul><p>Bot のオーナーは暗黙の owner エントリとして表示され、常に完全な権限を持ちます。システム管理者も完全な権限として解決されます。</p><p>ワークスペースの権限は次のとおりです:</p><table tabindex="0"><thead><tr><th>権限</th><th>許可される操作</th></tr></thead><tbody><tr><td><strong>チャット可</strong></td><td>Web のチャット画面で Bot を使う。</td></tr><tr><td><strong>ファイル読み取り</strong></td><td>Bot ワークスペースのファイルを読む。</td></tr><tr><td><strong>ファイル書き込み</strong></td><td>Bot ワークスペースのファイルを変更する。ファイル読み取りも暗黙的に含まれます。</td></tr><tr><td><strong>コマンド実行</strong></td><td>ワークスペースの実行フローを実行する。</td></tr><tr><td><strong>管理可</strong></td><td>Bot の設定とアクセス制御を管理する。他のすべてのワークスペース権限を暗黙的に含みます。</td></tr></tbody></table><p>ワークスペースの管理権限は、チャネルメンバーにも流れ込みます。ワークスペースの管理権限を持つユーザーが Telegram のアイデンティティを連携すると、その Telegram アイデンティティはチャネル側で管理権限を継承します。</p><p>ワークスペースの<strong>チャット可</strong>は、チャネルの<strong>チャット</strong>と同じではありません。ワークスペースの権限はクライアントとワークスペース API を許可するもので、チャネルのチャット権限は ACL エンジンを通じて IM の受信メッセージを許可するものです。</p><hr><h2 id="チャネルアイデンティティの連携" tabindex="-1">チャネルアイデンティティの連携 <a class="header-anchor" href="#チャネルアイデンティティの連携" aria-label="Permalink to &quot;チャネルアイデンティティの連携&quot;">​</a></h2><p>ユーザーは <strong>Profile -&gt; Connected Accounts</strong> で IM アイデンティティを連携できます:</p><ol><li><strong>Connect</strong> をクリックします。</li><li>生成された <code>/link &lt;code&gt;</code> コマンドをコピーします。</li><li>IM チャネルでいずれかの Memoh Bot にそれを送信します。</li><li>そのコードが、メッセージを送ったチャネルアイデンティティを現在の Memoh ユーザーアカウントに連携します。</li></ol><p>重要な詳細:</p><ul><li>link code は 1 回限りで、短時間で期限切れになります</li><li>送信者がチャットの ACL で拒否されていても <code>/link &lt;code&gt;</code> は実行を許可されるため、ユーザーは未連携の状態から復帰できます</li><li>連携はアカウントレベルです: ワークスペースユーザーとチャネルアイデンティティをグローバルにつなぎます</li><li>連携そのものがチャットや管理の権限を与えることはありません</li></ul><p>連携が完了すると、対応するチャネルメンバーの行がワークスペースの管理権限を継承できるようになります。</p><hr><h2 id="アクセスモードと高度な-acl-ルール" tabindex="-1">アクセスモードと高度な ACL ルール <a class="header-anchor" href="#アクセスモードと高度な-acl-ルール" aria-label="Permalink to &quot;アクセスモードと高度な ACL ルール&quot;">​</a></h2><p>チャネルのチャットは ACL エンジンを使います。アクセスページはそれを、<strong>アクセスモード</strong>と任意の高度なルールという形で見せています。</p><table tabindex="0"><thead><tr><th>アクセスモード</th><th>ACL のデフォルト効果</th><th>実際に結果へ影響するルール</th></tr></thead><tbody><tr><td><strong>ブラックリストモード</strong></td><td><code>allow</code></td><td><code>deny</code> ルール</td></tr><tr><td><strong>ホワイトリストモード</strong></td><td><code>deny</code></td><td><code>allow</code> ルール</td></tr></tbody></table><p>デフォルトモードを上書きするのは、現在のデフォルト効果と逆のルールだけです。デフォルトと同じ効果のルールは、結果を変えません。</p><p>高度なルールのターゲットには次を指定できます:</p><ul><li>すべてのユーザー</li><li>特定のプラットフォーム上のすべてのユーザー</li><li>特定のチャネルアイデンティティ</li><li>特定のプラットフォーム上の特定のチャネルアイデンティティ</li></ul><p>高度なルールのスコープには次を指定できます:</p><ul><li>任意のチャット</li><li>プライベートチャット</li><li>グループチャット</li><li>トピック／スレッド</li><li>特定の会話 ID</li><li>特定の thread ID</li></ul><p>プラットフォームの絞り込みはルールのターゲットが担当し、会話と thread の絞り込みはソースのスコープが担当します。</p><p>従来の ACL ドキュメントと違い、現在のバージョンには手動のルール優先度やドラッグによる並べ替えはありません。「現在のデフォルトモード + マッチした逆効果のルール」という形で理解してください。</p><hr><h2 id="作成時のプリセット" tabindex="-1">作成時のプリセット <a class="header-anchor" href="#作成時のプリセット" aria-label="Permalink to &quot;作成時のプリセット&quot;">​</a></h2><p>Bot の作成時に選ぶ ACL プリセットは、チャネルのチャット挙動を初期化するだけです。後から <strong>チャネルメンバー</strong> で変更できます。</p><table tabindex="0"><thead><tr><th>プリセット</th><th>初期挙動</th></tr></thead><tbody><tr><td><code>allow_all</code></td><td>デフォルト効果 <code>allow</code>。追加のルールは作成しない</td></tr><tr><td><code>private_only</code></td><td>デフォルト効果 <code>deny</code>。プライベートチャットを許可</td></tr><tr><td><code>group_only</code></td><td>デフォルト効果 <code>deny</code>。グループチャットを許可</td></tr><tr><td><code>group_and_thread_only</code></td><td>デフォルト効果 <code>deny</code>。グループチャットと thread を許可</td></tr><tr><td><code>deny_all</code></td><td>デフォルト効果 <code>deny</code>。追加の許可ルールは作成しない</td></tr></tbody></table><p>プリセットはワークスペースメンバーを設定せず、アカウント連携も作成しません。</p><hr><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><h3 id="公開-im-bot-で、少数だけブロックする" tabindex="-1">公開 IM Bot で、少数だけブロックする <a class="header-anchor" href="#公開-im-bot-で、少数だけブロックする" aria-label="Permalink to &quot;公開 IM Bot で、少数だけブロックする&quot;">​</a></h3><p>チャネルメンバーで<strong>ブラックリストモード</strong>を使います。チャットはデフォルトで開いたままにし、ブロックしたいアイデンティティだけを追加します。プラットフォーム全体や、特定のグループ／thread のコンテキストをブロックする必要があるときにだけ、高度なルールを使います。</p><h3 id="プライベート-im-bot" tabindex="-1">プライベート IM Bot <a class="header-anchor" href="#プライベート-im-bot" aria-label="Permalink to &quot;プライベート IM Bot&quot;">​</a></h3><p>チャネルメンバーで<strong>ホワイトリストモード</strong>を使います。許可するチャネルアイデンティティを追加し、チャットのチェックを維持します。同じ人たちに IM から Bot を管理させたい場合は、あわせて管理権限を与えます。</p><h3 id="web-チーム-bot" tabindex="-1">Web チーム Bot <a class="header-anchor" href="#web-チーム-bot" aria-label="Permalink to &quot;Web チーム Bot&quot;">​</a></h3><p><strong>ワークスペースメンバー</strong>を使います。特定のユーザーか、すべてのメンバーを追加し、Web／ワークスペースでの役割に応じてチャット可、ファイル権限、コマンド実行、管理権限を選びます。</p><h3 id="ワークスペース管理者が-telegram-からも管理する" tabindex="-1">ワークスペース管理者が Telegram からも管理する <a class="header-anchor" href="#ワークスペース管理者が-telegram-からも管理する" aria-label="Permalink to &quot;ワークスペース管理者が Telegram からも管理する&quot;">​</a></h3><p>ワークスペースメンバーでそのユーザーに<strong>管理可</strong>を与えます。ユーザーに <code>/link &lt;code&gt;</code> で Telegram アカウントを連携してもらいます。その Telegram アイデンティティは、チャネルメンバーで管理権限を継承します。そのアイデンティティの Telegram 側の管理能力だけを無効にしたい場合は、チャネルメンバーで管理権限をオフにしてローカルオーバーライドを作成します。</p><hr><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><p>アクセスの結果が予想と違うときは、次の順に確認してください:</p><ol><li><strong>どちらの層が関係しているか。</strong> IM のメッセージはチャネルのチャット ACL を通り、クライアントとワークスペース API はワークスペースメンバーを通ります。</li><li><strong>アイデンティティは連携済みか。</strong> Connected Accounts が、ワークスペースの管理権限をチャネルメンバーに継承できるかを決めます。</li><li><strong>現在のチャネルのアクセスモードは何か。</strong> ブラックリストモードはデフォルトで許可、ホワイトリストモードはデフォルトで拒否です。</li><li><strong>管理権限は継承か、オーバーライドか。</strong> チャネルメンバーの情報ポップオーバーに、管理権限がワークスペースメンバーに従っているのか、ローカルで上書きされているのかが表示されます。</li><li><strong><code>/access</code> は何を表示しているか。</strong> IM では、<code>/access</code> が現在のアイデンティティ、書き込み権限、送信者のチャット ACL コンテキストを表示します。</li></ol><p>管理とチャットは別物だということを覚えておいてください。管理権限は owner レベルの IM コマンドを許可できますが、通常の受信チャットは、チャネルのチャット権限が送信者を許可していなければ通りません。</p>',90)])])}const b=o(l,[["render",d]]);export{p as __pageData,b as default};
